// Watchlist: edit this list for a client. One item per ticker goes to "Fetch Prices".
// group: focus = full block at the top · investor = big Anthropic backers · ai = AI sector
// ipoPrice (optional): shows "since IPO" for new listings.
const WATCHLIST = [
  { symbol: 'ANT',   name: 'Anthropic', group: 'focus', ipoPrice: 83 },
  { symbol: 'AMZN',  name: 'Amazon',    group: 'investor' },
  { symbol: 'GOOGL', name: 'Alphabet',  group: 'investor' },
  { symbol: 'NVDA',  name: 'Nvidia',    group: 'ai' },
  { symbol: 'MSFT',  name: 'Microsoft', group: 'ai' },
  { symbol: 'META',  name: 'Meta',      group: 'ai' },
  { symbol: 'AMD',   name: 'AMD',       group: 'ai' },
  { symbol: 'AVGO',  name: 'Broadcom',  group: 'ai' },
  { symbol: 'TSM',   name: 'TSMC',      group: 'ai' },
  { symbol: 'PLTR',  name: 'Palantir',  group: 'ai' }
];
return WATCHLIST.map(w => ({ json: w }));

// Compute Stats: turns Yahoo chart responses into one clean row per ticker.
// Pairs each response with its watchlist item by position (the HTTP node keeps the order).
const BIG_MOVE_PCT = 5; // flag moves of ±5% or more in one day
const watch = $('Watchlist').all().map(i => i.json);
const responses = $input.all().map(i => i.json);

const pct = (a, b) => (a != null && b ? ((a - b) / b) * 100 : null);
const round = (x, d = 2) => (x == null || isNaN(x) ? null : Math.round(x * 10 ** d) / 10 ** d);

function parse(w, res) {
  const r = res && res.chart && res.chart.result && res.chart.result[0];
  if (!r) {
    const why = (res && res.chart && res.chart.error && res.chart.error.description)
      || (res && res.error && (res.error.message || res.error)) || 'no data';
    return { ...w, ok: false, error: String(why).slice(0, 120) };
  }
  const q = r.indicators.quote[0];
  const bars = (r.timestamp || [])
    .map((t, i) => ({ t, close: q.close[i], volume: q.volume[i] }))
    .filter(b => b.close != null);
  if (!bars.length) return { ...w, ok: false, error: 'no closing prices' };

  const last = bars[bars.length - 1];
  // First trading day: compare with the IPO price.
  const prev = bars.length > 1 ? bars[bars.length - 2].close : (w.ipoPrice || r.meta.chartPreviousClose);
  const weekAgo = bars.length > 5 ? bars[bars.length - 6].close : null;
  const monthStart = bars.length > 15 ? bars[0].close : null;
  const prevVols = bars.slice(0, -1).map(b => b.volume).filter(Boolean);
  const avgVol = prevVols.length ? prevVols.reduce((a, b) => a + b, 0) / prevVols.length : null;
  const day = pct(last.close, prev);

  return {
    ...w,
    ok: true,
    currency: r.meta.currency || 'USD',
    date: new Date(last.t * 1000).toISOString().slice(0, 10),
    close: round(last.close),
    dayPct: round(day),
    weekPct: round(pct(last.close, weekAgo)),
    monthPct: round(pct(last.close, monthStart)),
    sinceIpoPct: w.ipoPrice ? round(pct(last.close, w.ipoPrice)) : null,
    high52: r.meta.fiftyTwoWeekHigh != null ? round(r.meta.fiftyTwoWeekHigh) : null,
    low52: r.meta.fiftyTwoWeekLow != null ? round(r.meta.fiftyTwoWeekLow) : null,
    volume: last.volume,
    volVsAvg: avgVol ? round(last.volume / avgVol, 1) : null,
    tradingDays: bars.length,
    bigMove: day != null && Math.abs(day) >= BIG_MOVE_PCT
  };
}

return watch.map((w, i) => ({ json: parse(w, responses[i]) }));

// News Queries: one Google News RSS search per topic (last 24 hours, English, US edition).
// For a paying client, swap this for a licensed news API (see README).
const TOPICS = [
  { topic: 'anthropic', label: 'Anthropic', q: '(Anthropic OR "ANT stock" OR "Claude AI") when:1d', max: 6 },
  // exclude: skip headlines with these words (Anthropic stories already have their own section)
  { topic: 'ai', label: 'AI stocks', exclude: ['anthropic'], q: '("AI stocks" OR "Nvidia stock" OR "Nvidia shares" OR "chip stocks" OR "AI bubble") when:1d', max: 6 }
];
return TOPICS.map(t => ({
  json: { ...t, url: 'https://news.google.com/rss/search?q=' + encodeURIComponent(t.q) + '&hl=en-US&gl=US&ceid=US:en' }
}));

// Parse News: RSS → headlines. Drops duplicates (across topics and vs. the last 3 days),
// then returns ONE item with the prompt for the AI brief, so the flow never stops on a quiet day.
const topics = $('News Queries').all().map(i => i.json);
const feeds = $input.all().map(i => i.json);
const stats = $('Compute Stats').all().map(i => i.json);

const decode = s => String(s || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ').trim();
const tag = (xml, t) => {
  const m = xml.match(new RegExp('<' + t + '[^>]*>([\\s\\S]*?)</' + t + '>'));
  return m ? decode(m[1]) : '';
};
// Same story from two outlets usually shares its first long words.
const key = title => title.toLowerCase().replace(/[^a-z0-9 ]/g, '').split(' ')
  .filter(w => w.length > 3).slice(0, 6).join(' ');

// Remember headlines already sent (kept only in production runs, not manual tests).
const store = $getWorkflowStaticData('global');
const now = Date.now();
const seen = store.seenNews || {};
for (const k of Object.keys(seen)) if (now - seen[k] > 3 * 864e5) delete seen[k];

const used = new Set();
const out = {};
const errors = [];
topics.forEach((t, i) => {
  const xml = feeds[i] && typeof feeds[i].data === 'string' ? feeds[i].data : '';
  if (!xml.includes('<rss')) errors.push(t.label + ' feed not reached');
  const items = (xml.match(/<item>[\s\S]*?<\/item>/g) || []).map(x => {
    let title = tag(x, 'title');
    const source = tag(x, 'source');
    if (source && title.endsWith(' - ' + source)) title = title.slice(0, -(source.length + 3));
    const d = new Date(tag(x, 'pubDate'));
    return { title, source, link: tag(x, 'link'), published: isNaN(d) ? '' : d.toISOString() };
  }).filter(n => n.title && n.link);
  items.sort((a, b) => b.published.localeCompare(a.published));
  out[t.topic] = [];
  const exclude = (t.exclude || []).map(w => w.toLowerCase());
  for (const n of items) {
    const k = key(n.title);
    if (!k || used.has(k) || seen[k]) continue;
    if (exclude.some(w => n.title.toLowerCase().includes(w))) continue;
    used.add(k);
    out[t.topic].push(n);
    if (out[t.topic].length >= t.max) break;
  }
});
for (const k of used) seen[k] = now;
store.seenNews = seen;

const fmt = s => s.ok
  ? `${s.symbol} (${s.name}) close ${s.close} ${s.currency}, day ${s.dayPct}%`
    + (s.weekPct != null ? `, 5d ${s.weekPct}%` : '')
    + (s.sinceIpoPct != null ? `, since IPO ${s.sinceIpoPct}% (trading day ${s.tradingDays})` : '')
    + (s.volVsAvg != null ? `, volume ${s.volVsAvg}x average` : '')
  : `${s.symbol}: no data`;
const list = arr => arr.map((n, i) => `${i + 1}. ${n.title} (${n.source})`).join('\n') || 'none';

const prompt = [
  'PRICES (last US close):', stats.map(fmt).join('\n'),
  '', 'ANTHROPIC HEADLINES (24h):', list(out.anthropic || []),
  '', 'AI SECTOR HEADLINES (24h):', list(out.ai || [])
].join('\n');

return [{ json: { anthropic: out.anthropic || [], ai: out.ai || [], errors, prompt } }];

