{
  "type": "object",
  "properties": {
    "headline": {
      "type": "string",
      "description": "One sentence, max 110 characters: the main story of the day"
    },
    "anthropic": {
      "type": "string",
      "description": "Max 2 sentences (280 characters) on Anthropic (ANT): price move and the news behind it"
    },
    "ai_market": {
      "type": "string",
      "description": "Max 2 sentences (280 characters) on AI stocks overall: leaders, laggards, theme of the day"
    },
    "watch": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "0 to 3 upcoming events or open questions named in the headlines (earnings dates, lock-up, index inclusion). Max 90 characters each. Empty if none."
    }
  },
  "required": [
    "headline",
    "anthropic",
    "ai_market",
    "watch"
  ]
}

