// Build Message: Telegram HTML. Works with or without the AI brief.
// Splits into several messages if longer than Telegram's 4,096-character limit.
const stats = $('Compute Stats').all().map(i => i.json);
const news = $('Parse News').first().json;
const ai = $input.first().json;
const brief = ai && ai.output && typeof ai.output === 'object' ? ai.output : null;

const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const sign = x => (x == null ? 'n/a' : (x > 0 ? '+' : '') + x.toFixed(2) + '%');
const arrow = x => (x == null ? '▫️' : x >= 0 ? '🟢' : '🔴');
const money = x => '$' + Number(x).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const vol = v => (v >= 1e9 ? (v / 1e9).toFixed(2) + 'B' : v >= 1e6 ? (v / 1e6).toFixed(1) + 'M' : String(v || 0));

const ok = stats.filter(s => s.ok);
const failed = stats.filter(s => !s.ok);
const day = ok.length ? ok.map(s => s.date).sort().pop() : new Date().toISOString().slice(0, 10);
const lines = [`📈 <b>AI Stock Watch</b> · US close ${day}`];

if (brief && brief.headline) lines.push('', '<b>' + esc(brief.headline) + '</b>');

for (const s of ok.filter(x => x.group === 'focus')) {
  lines.push('', `${arrow(s.dayPct)} <b>${esc(s.name)} (${s.symbol})</b> ${money(s.close)}  <b>${sign(s.dayPct)}</b>`);
  const extra = [];
  if (s.sinceIpoPct != null) extra.push(`since IPO ${sign(s.sinceIpoPct)} (IPO ${money(s.ipoPrice)}, trading day ${s.tradingDays})`);
  if (s.weekPct != null) extra.push(`5d ${sign(s.weekPct)}`);
  if (s.high52 != null) extra.push(`range ${money(s.low52)}–${money(s.high52)}`);
  extra.push(`vol ${vol(s.volume)}${s.volVsAvg ? ` (${s.volVsAvg}x avg)` : ''}`);
  lines.push(extra.join(' · '));
  if (brief && brief.anthropic) lines.push('<i>' + esc(brief.anthropic) + '</i>');
}

const others = ok.filter(x => x.group !== 'focus').sort((a, b) => (b.dayPct ?? -999) - (a.dayPct ?? -999));
if (others.length) {
  lines.push('', '<b>AI stocks</b> (close · day · 5 days)');
  for (const s of others) {
    lines.push(`${arrow(s.dayPct)} <code>${s.symbol.padEnd(5)}</code> ${money(s.close)} · ${sign(s.dayPct)} · ${sign(s.weekPct)}`
      + (s.bigMove ? ' ⚠️' : '') + (s.group === 'investor' ? ' 🤝' : ''));
  }
  lines.push('<i>🤝 major Anthropic investor · ⚠️ moved 5%+ today</i>');
}
if (brief && brief.ai_market) lines.push('', '🧭 ' + esc(brief.ai_market));
if (brief && Array.isArray(brief.watch) && brief.watch.length) {
  lines.push('', '<b>Worth watching</b>', ...brief.watch.slice(0, 3).map(w => '• ' + esc(w)));
}

const newsBlock = (title, arr) => (arr.length
  ? ['', `<b>${title}</b>`, ...arr.map(n => `• <a href="${esc(n.link)}">${esc(n.title)}</a> <i>(${esc(n.source)})</i>`)]
  : []);
lines.push(...newsBlock('📰 Anthropic news', news.anthropic || []));
lines.push(...newsBlock('📰 AI sector news', news.ai || []));

const problems = [];
if (failed.length) problems.push('no price for ' + failed.map(f => f.symbol).join(', '));
if (news.errors && news.errors.length) problems.push(news.errors.join(', '));
if (!brief) problems.push('AI brief skipped');
if (problems.length) lines.push('', '⚙️ <i>' + esc(problems.join(' · ')) + '</i>');
lines.push('', '<i>Automated summary of public data. Not financial advice.</i>');

// Telegram counts 4,096 characters AFTER removing tags (link URLs do not count).
// Split on line boundaries, keeping a margin.
const visible = s => s.replace(/<[^>]+>/g, '').replace(/&lt;|&gt;|&amp;/g, 'x').length;
const chunks = [];
let cur = '';
for (const l of lines) {
  if (cur && visible(cur + '\n' + l) > 3900) { chunks.push(cur); cur = l; } else cur = cur ? cur + '\n' + l : l;
}
if (cur) chunks.push(cur);
return chunks.map((text, i) => ({ json: { text, part: i + 1, parts: chunks.length } }));
